{"command":"function Read-GitObject($sha) {
  $dir = $sha.Substring(0,2); $file = $sha.Substring(2);
  $p = Join-Path './workspace/.git/objects' ($dir + '/' + $file);
  if (-not (Test-Path $p)) { return $null }
  $bytes = [System.IO.File]::ReadAllBytes((Resolve-Path $p));
  $ms = New-Object System.IO.MemoryStream(,$bytes[2..($bytes.Length-1)]);
  $ds = New-Object System.IO.Compression.DeflateStream($ms,[System.IO.Compression.CompressionMode]::Decompress);
  $out = New-Object System.IO.MemoryStream; $ds.CopyTo($out); $ds.Close();
  return $out.ToArray();
}
$global:list = New-Object System.Collections.Generic.List[string]
function Walk-Tree($sha, $prefix) {
  $raw = Read-GitObject $sha; if ($null -eq $raw) { Write-Output "MISSING TREE $sha"; return }
  $i = 0;
  while ($i -lt $raw.Length) {
    $sp = [Array]::IndexOf($raw, [byte]0x20, $i);
    $mode = [System.Text.Encoding]::ASCII.GetString($raw, $i, $sp - $i);
    $nul = [Array]::IndexOf($raw, [byte]0, $sp+1);
    $name = [System.Text.Encoding]::ASCII.GetString($raw, $sp+1, $nul - ($sp+1));
    $shaBytes = New-Object byte[] 20; [Array]::Copy($raw, $nul+1, $shaBytes, 0, 20);
    $hex = -join ($shaBytes | ForEach-Object { $_.ToString('x2') });
    if ($mode -eq '40000') { Walk-Tree $hex ($prefix + $name + '/') }
    else { $global:list.Add($prefix + $name) }
    $i = $nul + 21;
  }
}
